import itertools
class PortfolioTracker:
    def __init__(self):
        self.cash = 1000
        self.shares = 0
        self.transactions = []

    def __call__(self, prev_state, trade):
        action, price, quantity = trade
        if action == 'buy' and self.cash >= price * quantity:
            self.cash -= price * quantity
            self.shares += quantity
            self.transactions.append(trade)
        elif action == 'sell' and self.shares >= quantity:
            self.cash += price * quantity
            self.shares -= quantity
            self.transactions.append(trade)
        return (self.cash, self.shares, len(self.transactions))

